  const tabs = [['pos', 'Positions (' + op.length + ')'], ['ord', 'Orders (' + pd.length + ')'], ['hist', 'Trade history'], ['ana', 'Analytics']].map(t => '<button data-a="tab" data-t="' + t[0] + '" class="' + (tab === t[0] ? 'on' : '') + '">' + t[1] + '</button>').join('');
  let body = '';
  if(tab === 'pos') body = op.length ? '<table><thead><tr><th>Ticker</th><th>Side</th><th>Qty</th><th>Entry</th><th>Live</th><th>P/L</th><th>Stop</th><th>Target</th><th></th></tr></thead><tbody>' + op.map(t => { const u = upnl(t, px); return '<tr><td><button class="go" data-a="chart" data-s="' + E(t.sym) + '">' + E(t.sym) + ' 📈</button></td><td class="' + (t.side === 'long' ? 'up' : 'dn') + '">' + t.side + (t.lev > 1 ? ' ' + t.lev + '×' : '') + '</td><td>' + +t.qty.toPrecision(5) + '</td><td>' + fx(t.entry) + '</td><td>' + (px[t.sym] ? fx(px[t.sym]) : '–') + '</td><td class="' + (u >= 0 ? 'up' : 'dn') + '">' + usd(u) + ' (' + n2(u / t.margin * 100, 1) + '%)</td><td>' + (t.sl ? fx(t.sl) : '–') + '</td><td>' + (t.tp ? fx(t.tp) : '–') + '</td><td><button class="btn" data-a="edit" data-id="' + t.id + '">SL/TP</button> <button class="btn" data-a="close" data-id="' + t.id + '">Close</button></td></tr>'; }).join('') + grpAvg(op).map(a => { const lp = px[a.sym], u = lp > 0 ? (lp - a.avg) * a.qty * (a.side === 'long' ? 1 : -1) : 0; return '<tr style="background:rgba(219,161,24,.08)"><td><b>' + E(a.sym) + '</b> <span class="sub">average of ' + a.n + ' fills</span></td><td class="' + (a.side === 'long' ? 'up' : 'dn') + '">' + a.side + '</td><td>' + +a.qty.toPrecision(5) + '</td><td><b>' + fx(a.avg) + '</b></td><td>' + (lp ? fx(lp) : '–') + '</td><td class="' + (u >= 0 ? 'up' : 'dn') + '">' + usd(u) + ' (' + n2(u / a.margin * 100, 1) + '%)</td><td colspan="3"></td></tr>'; }).join('') + '</tbody></table>' : '<p class="sub">Make a trade to get started. Pick Buy or Sell on the ticket.</p>';
